[CmdletBinding()]
param([Parameter(Mandatory)][string]$RelayAddress,[int]$Port=3000,[Parameter(Mandatory)][ValidateSet('Allowed','Denied')][string]$Expected,[Parameter(Mandatory)][string]$ProbeRole,[string]$OutputPath)
$ErrorActionPreference='Stop';$r=Test-NetConnection -ComputerName $RelayAddress -Port $Port -InformationLevel Detailed;$reachable=[bool]$r.TcpTestSucceeded;$passed=if($Expected-eq'Allowed'){$reachable}else{-not$reachable};$e=[ordered]@{tested_at=[DateTimeOffset]::UtcNow.ToString('o');probe_host=$env:COMPUTERNAME;probe_role=$ProbeRole;relay=$RelayAddress;port=$Port;expected=$Expected;reachable=$reachable;passed=$passed};$j=$e|ConvertTo-Json;if($OutputPath){$j|Set-Content $OutputPath -Encoding utf8}else{$j};if(-not$passed){throw "Reachability proof failed for $ProbeRole ($Expected)."}
